/**
 * [INPUT]: 依赖 ProviderConnectionService、admin 上下文与权限边界。
 * [OUTPUT]: 提供供应商连接 list/get/create/update；连接测试由独立入口负责。
 * [POS]: model/web 的连接管理入口，密钥只进入短生命周期 command。
 * [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
 */
package com.owndsh.enterprise.model.web;
import cn.dev33.satoken.annotation.SaCheckPermission;import jakarta.servlet.http.HttpServletRequest;import com.owndsh.enterprise.auth.web.*;import com.owndsh.enterprise.common.api.*;import com.owndsh.enterprise.model.application.*;import com.owndsh.enterprise.model.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/enterprise/admin/v1/providers/{providerId}/connections") public final class AdminProviderConnectionController{
 private final ProviderConnectionService service;private final IdentityAdminRequestContextResolver contexts;private final EnterpriseCursorCodec cursors;public AdminProviderConnectionController(ProviderConnectionService s,IdentityAdminRequestContextResolver c,EnterpriseCursorCodec cursors){service=s;contexts=c;this.cursors=cursors;}
 @GetMapping @SaCheckPermission("ent:model:read") public EnterpriseResponse<CursorPageData<ProviderConnectionView>> list(@PathVariable long providerId,@RequestParam(required=false) String cursor,@RequestParam(defaultValue="50") int limit,HttpServletRequest req){var c=contexts.resolve(req);int pageLimit=EnterpriseApiValidation.requirePageLimit(limit);long afterId=cursors.decode(cursor,c.tenantId(),"provider_connections");var fetched=service.list(c.tenantId(),providerId,afterId,pageLimit+1);boolean hasMore=fetched.size()>pageLimit;var items=hasMore?fetched.subList(0,pageLimit):fetched;String next=hasMore?cursors.encode(c.tenantId(),"provider_connections",items.getLast().id()):null;return response(new CursorPageData<>(items.stream().map(ProviderConnectionView::from).toList(),new CursorPageMetadata(hasMore,pageLimit,next)),c);}
 @GetMapping("/{connectionId}") @SaCheckPermission("ent:model:read") public EnterpriseResponse<ProviderConnectionView> get(@PathVariable long providerId,@PathVariable long connectionId,HttpServletRequest req){var c=contexts.resolve(req);return response(ProviderConnectionView.from(requireOwned(c.tenantId(),providerId,connectionId)),c);}
 @PostMapping @SaCheckPermission("ent:model:write") public ResponseEntity<EnterpriseResponse<ProviderConnectionView>> create(@PathVariable long providerId,@RequestHeader("Idempotency-Key") UUID key,@RequestBody ProviderConnectionWriteRequest body,HttpServletRequest req){EnterpriseApiValidation.requireUuidV4(key,"Idempotency-Key");var c=contexts.resolve(req);try(body;var secret=body.createSecret()){return ResponseEntity.status(HttpStatus.CREATED).body(response(ProviderConnectionView.from(service.create(mutation(c),providerId,body.spec(),secret)),c));}}
 @PutMapping("/{connectionId}") @SaCheckPermission("ent:model:write") public EnterpriseResponse<ProviderConnectionView> update(@PathVariable long providerId,@PathVariable long connectionId,@RequestHeader("If-Match") long rev,@RequestBody ProviderConnectionWriteRequest body,HttpServletRequest req){var c=contexts.resolve(req);var owned=requireOwned(c.tenantId(),providerId,connectionId);try(body;var secret=body.replacement()){return response(ProviderConnectionView.from(service.update(mutation(c),connectionId,rev,body.spec(owned.apiProtocol()),Boolean.TRUE.equals(body.replaceSecret()),secret)),c);}}

 private ProviderConnection requireOwned(String tenant,long providerId,long connectionId){var connection=service.get(tenant,connectionId);if(connection.providerId()!=providerId)throw new ModelResourceNotFoundException();return connection;}

 private static ModelMutationContext mutation(EnterpriseRequestContext c){return new ModelMutationContext(c.tenantId(),c.actorId(),c.requestId(),c.sourceIp(),c.userAgentHash());}private static <T>EnterpriseResponse<T> response(T d,EnterpriseRequestContext c){return new EnterpriseResponse<>(d,c.requestId());}
}
